import duckdb
con = duckdb.connect(r"D:\repository\数据湖\data\cnequity\duckdb\cnequity.duckdb", read_only=True)

def desc(t):
    print("==", t, "==")
    for r in con.execute(f"describe {t}").fetchall():
        print("  ", r[0], r[1])

for t in ["valuation_metrics", "daily_bars", "daily_bars_adj", "corporate_actions", "instruments"]:
    desc(t)

codes = ['601000','600461','601077','601298','601033','000651','000001','000598','000429']
inlist = "','".join(codes)
for t in ["valuation_metrics", "daily_bars", "daily_bars_adj"]:
    cols = [c[0] for c in con.execute(f"describe {t}").fetchall()]
    codecol = 'code' if 'code' in cols else ('symbol' if 'symbol' in cols else cols[0])
    datecol = 'trade_date' if 'trade_date' in cols else ('date' if 'date' in cols else cols[1])
    print(f"\n-- {t} sample for 601000 --")
    try:
        rows = con.execute(f"select * from {t} where {codecol}='601000' order by {datecol} desc limit 3").fetchall()
        print("cols:", cols)
        for r in rows: print(r)
        cnt = con.execute(f"select count(*), min({datecol}), max({datecol}) from {t} where {codecol}='601000'").fetchone()
        print("count/range:", cnt)
    except Exception as e:
        print("ERR", e)

print("\n-- corporate_actions sample 601000 --")
cols = [c[0] for c in con.execute("describe corporate_actions").fetchall()]
print("cols:", cols)
try:
    for r in con.execute("select * from corporate_actions where code='601000' order by ex_date desc limit 5").fetchall():
        print(r)
except Exception as e:
    print("ERR", e)
    for r in con.execute("select * from corporate_actions limit 3").fetchall():
        print(r)

