1: // 持仓面板逻辑自测：在 Node 里跑真实 sql.js，验证成本 / 盈亏 / 分红 / 费用口径
2: // 用法：node _selftest.js
3: const fs = require('fs'), path = require('path'), vm = require('vm');
4: const dir = __dirname;
5: const html = fs.readFileSync(path.join(dir, 'index.html'), 'utf8');
6: 
7: // 主脚本 = 最后一个 <script>...</script>（前面是 sql.js 与 wasm base64）
8: const m = html.match(/<script>\n\(function \(\) \{\n'use strict';\n\n\/\* =+ 常量[\s\S]*?<\/script>/);
9: if (!m) throw new Error('找不到主脚本');
10: const main = m[0].replace(/^<script>\n/, '').replace(/<\/script>$/, '');
11: 
12: const els = {};
13: function el(id) {
14:   if (!els[id]) els[id] = {
15:     id, innerHTML: '', textContent: '', value: '', style: {}, className: '', dataset: {},
16:     classList: { toggle() {}, add() {}, remove() {}, contains() { return false; } },
17:     addEventListener() {}, setAttribute() {}, getAttribute() { return null; },
18:     querySelector() { return null; }, closest() { return null; }, focus() {}
19:   };
20:   return els[id];
21: }
22: 
23: // sql.js 的 WASM 从页面里内联的那段 base64 取，测试脚本不依赖任何 npm 包
24: const wasmB64 = html.match(/id="sqlWasmB64">([\s\S]*?)<\/script>/)[1];
25: els['sqlWasmB64'] = { textContent: wasmB64, id: 'sqlWasmB64' };
26: 
27: const sandbox = {
28:   console, Date, Math, Number, String, Object, Array, JSON, isNaN, isFinite,
29:   parseFloat, parseInt, atob: s => Buffer.from(s, 'base64').toString('binary'),
30:   setTimeout: () => 0, setInterval: () => 0, clearTimeout: () => {}, clearInterval: () => {},
31:   confirm: () => true, alert: () => {},
32:   indexedDB: { open() { return {}; } },
33:   localStorage: { getItem: () => null, setItem: () => {} },
34:   document: {
35:     getElementById: el,
36:     querySelector: s => el(s.replace(/^#/, '')),
37:     querySelectorAll: () => [],
38:     addEventListener: () => {},
39:     createElement: () => ({ style: {}, dataset: {}, remove() {}, click() {}, appendChild() {}, setAttribute() {} }),
40:     head: { appendChild() {} }, body: { appendChild() {} }
41:   },
42:   fetch: () => Promise.reject(new Error('no net')),
43:   location: { search: '' },
44:   FileReader: function () {},
45:   Blob: function () {}, URL: { createObjectURL: () => '', revokeObjectURL() {} }
46: };
47: sandbox.window = sandbox;
48: sandbox.self = sandbox;
49: sandbox.globalThis = sandbox;
50: vm.createContext(sandbox);
51: 
52: // config.js 是可选依赖，存在就注入
53: const cfgPath = path.join(dir, 'config.js');
54: if (fs.existsSync(cfgPath)) vm.runInContext(fs.readFileSync(cfgPath, 'utf8'), sandbox);
55: // sql.js 加载器（页面里内联的那段）也跑进同一个沙箱，得到 initSqlJs
56: const loader = html.match(/<!-- SQLJS:START[^>]*-->\s*<script>([\s\S]*?)<\/script>/);
57: if (!loader) throw new Error('找不到 sql.js 加载器');
58: vm.runInContext(loader[1], sandbox);
59: if (typeof sandbox.initSqlJs !== 'function') throw new Error('sql.js 加载器没有导出 initSqlJs');
60: vm.runInContext(main, sandbox);
61: 
62: const P = sandbox.__PANEL__;
63: let fail = 0;
64: const ok = (cond, msg) => { console.log((cond ? '  PASS ' : '  FAIL ') + msg); if (!cond) fail++; };
65: const near = (a, b, eps) => Math.abs(a - b) < (eps == null ? 0.01 : eps);
66: const strip = s => String(s || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
67: 
68: (async () => {
69:   // 直接用页面内联的 sql.js 引擎，不依赖 npm
70:   const SQL = await P._ensureSql();
71:   const d = new SQL.Database();
72:   const SCHEMA = html.match(/const SCHEMA = `([\s\S]*?)`;/)[1];
73:   d.exec(SCHEMA);
74:   P._setDb(d);
75:   P._seedInto(d);
76:   P._readState();
77: 
78:   const run = (sql, p) => { d.run(sql, p); };
79:   const addTrade = (acct, code, name, side, date, sh, px, fee) =>
80:     run('INSERT INTO trade(acct,code,name,side,date,shares,price,fee,note) VALUES(?,?,?,?,?,?,?,?,?)',
81:       [acct, code, name, side, date, sh, px, fee || 0, '']);
82:   const addDiv = (acct, code, name, date, amt, tax) =>
83:     run('INSERT INTO dividend(acct,code,name,date,amount,tax,note) VALUES(?,?,?,?,?,?,?)',
84:       [acct, code, name, date, amt, tax || 0, '']);
85: 
86:   /* ---------- 1. 费用口径 ---------- */
87:   console.log('\n--- 交易费用 ---');
88:   const S = P.S;
89:   ok(near(S.settings.comm, 0.0000854, 1e-9), '佣金费率默认万分之 0.854');
90:   ok(near(S.settings.minFee, 5, 1e-9), '最低佣金默认 5 元');
91:   // 小额：1000 元成交，佣金 0.0854 元 < 5，取 5
92:   const f1 = P.calcFee('buy', 1000);
93:   ok(near(f1, 5 + 1000 * 0.00001, 0.005), '小额买入走最低佣金 5 元 + 过户费，实得 ' + f1.toFixed(2));
94:   // 大额：10 万，佣金 8.54 元 > 5
95:   const f2 = P.calcFee('buy', 100000);
96:   ok(near(f2, 8.54 + 1, 0.02), '10 万买入 = 佣金 8.54 + 过户费 1 = ' + f2.toFixed(2));
