  const body = $('#planBody'), note = $('#planNote');
  const COLS = 9;
  const hasMargin = rows.some(r => r.margin);
  if (!amount) { body.innerHTML = '<tr><td colspan="' + COLS + '" class="dim" style="text-align:center;padding:16px">config.js 未给出 rules.capital。</td></tr>'; return; }
  if (!rows.length) {
    body.innerHTML = '<tr><td colspan="' + COLS + '" class="dim" style="text-align:center;padding:16px">先记一笔买入，或等 config.js 生成目标清单。</td></tr>';
    note.textContent = '买入推荐依赖 config.js 的目标权重；安全边际指标来自 panel_margin_metrics.py（缺失则退化为 60 日均价口径）。';
    return;
  }
  const res = buildPlan(amount, rows, T);

  // 目标买价单元格（股息率绝对值阈值）：现价 <= 目标价 达标
  const tgtCell = r => {
    const mg = r.margin;
    if (!mg || !(mg.targetBuyAbsolute > 0)) return '<td class="num dim">—</td>';
    const hit = r.buyToTgtPct != null && r.buyToTgtPct >= 0;
    return '<td class="num"><b class="' + (hit ? 'gold' : '') + '">' + fmt(mg.targetBuyAbsolute, 2) + '</b>' +
      '<small class="tx3">/' + fmt(mg.targetYld, 1) + '%</small></td>';
  };
  // 距买点：现价低于目标价多少（正=已达标，可买；负=还差多少才跌到）
  const distCell = r => {
    if (r.buyToTgtPct == null) return '<td class="num dim">—</td>';
    if (r.buyToTgtPct >= 0) return '<td class="num gold">达标 <small>+' + fmt(r.buyToTgtPct, 1) + '%</small></td>';
    return '<td class="num dim">还差 ' + fmt(-r.buyToTgtPct, 1) + '%</td>';
  };
  // 股息率分位（近 3 年）：>=80 高安全边际
  const pctCell = r => {
    const p = r.margin && r.margin.yldPct;
    if (p == null) return '<td class="num dim">—</td>';
    const hi = p >= 80;
    return '<td class="num ' + (hi ? 'gold' : '') + '">' + fmt(p, 0) + '<small class="tx3">%位</small></td>';
  };
  // 布林带：显示 60 日下轨，触底标绿
  const bollCell = r => {
    const b = r.boll60 || r.boll20;
    if (!b) return '<td class="num dim">—</td>';
    return '<td class="num ' + (b.belowLower ? 'gold' : '') + '">' + fmt(b.lower, 2) +
      '<small class="tx3">' + (b.belowLower ? ' 触底' : ' ' + fmt(b.distToLowerPct, 1) + '%') + '</small></td>';
  };

  const pendHtml = res.skipped.map(x => {
    const r = x.r, mg = r.margin;
    if (mg && mg.targetBuyAbsolute > 0 && r.buyToTgtPct != null && r.buyToTgtPct < 0) {
      return '<b>' + esc(r.name) + '</b> 跌到 <b>' + fmt(mg.targetBuyAbsolute, 2) + '</b> 元（股息率 ' + fmt(mg.targetYld, 1) + '%）';
    }
    const v = r.t && r.t.vwap60;
    return '<b>' + esc(r.name) + '</b>' + (v ? ' 跌到 <b>' + fmt(v * (1 - (+RULES.skip_premium || 3) / 100), 2) + '</b> 元以下' : '') + (x.why ? '（' + esc(x.why) + '）' : '');
  }).join('、');

  if (!res.items.length) {
    body.innerHTML = '<tr><td colspan="' + COLS + '" class="dim" style="text-align:center;padding:16px">本轮不买。</td></tr>';
    note.innerHTML = '<b>没有值得现在买的。</b>' +
      (hasMargin ? '<br>股息率/分位/布林带均未触发买点，钱先留着买逆回购。' : '') +
      (res.skipped.length ? '<br>参考买点：' + pendHtml + '。' : '') +
      '<br>钱先留着，买在什么价位比买没买更重要。';
    return;
  }

  body.innerHTML = res.items.map(x => {
    const after = res.base > 0 ? (x.r.mv + x.cost) / res.base * 100 : 0;
    return '<tr><td class="nm"><b>' + esc(x.r.name) + '</b><small>' + esc(x.r.code) + '</small></td>' +
      '<td class="num">' + fmt(x.r.price) + '</td>' +
      tgtCell(x.r) + distCell(x.r) + pctCell(x.r) + bollCell(x.r) +
      '<td class="num"><b>' + fmt(x.shares, 0) + '</b></td>' +
      '<td class="num">' + fmt(x.cost, 0) + '</td>' +
      '<td class="num">' + fmt(after, 2) + '% <span class="tx3">/' + fmt(x.r.capPct, 2) + '</span></td></tr>';
  }).join('');

  const best = res.items.slice().sort((a, b) =>
    (b.r.marginStrength || 0) - (a.r.marginStrength || 0) ||
    ((b.r.buyToTgtPct || 0) - (a.r.buyToTgtPct || 0)))[0];
  const bestTxt = (() => {
    const r = best.r, mg = r.margin;
    if (mg) {
      const parts = [];
      parts.push('股息率 ' + fmt(r.yldNow, 2) + '%');
      if (mg.yldPct != null) parts.push('近3年分位 ' + fmt(mg.yldPct, 0) + '%');
      if (mg.targetBuyAbsolute > 0) parts.push('目标买价 ' + fmt(mg.targetBuyAbsolute, 2) + (r.buyToTgtPct >= 0 ? '（已达标）' : ''));
      if (r.boll60 && r.boll60.belowLower) parts.push('触及布林下轨');
      return '优先 <b>' + esc(r.name) + '</b>：' + parts.join('，') + '。';
    }
    return '优先 <b>' + esc(r.name) + '</b>：较 60 日均价' + (r.disc > 0 ? '低' : '高') + ' ' + fmt(Math.abs(r.disc), 1) + '%，股息率 ' + fmt(r.yldNow, 2) + '%。';
  })();
  const full = res.skipped;
  note.innerHTML = '合计 <b>' + fmt(res.spend, 0) + ' 元</b>' +
    (res.left > 60 ? '，剩 <b>' + fmt(res.left, 0) + ' 元</b> 留现金' : '') + '。' +
    '<br>' + bestTxt +
    (full.length ? '<br><span class="tx3">其它：' + full.map(x => esc(x.r.name) + '（' + esc(x.why) + '）').join('、') + '</span>' : '');
}

