console.log('\n--- 安全边际指标 ---');
if (typeof P.marginOf === 'function' && sandbox.PANEL_MARGIN) {
  ok(P._marginCount() > 0, '已加载安全边际指标 ' + P._marginCount() + ' 只');
  const mg = P.marginOf('600461');
  ok(!!mg, 'marginOf("600461") 命中洪城环境 → ' + (mg ? mg.name : 'null'));
  ok(mg && mg.targetBuyAbsolute > 0, '洪城环境目标买价 > 0 → ' + (mg && mg.targetBuyAbsolute));
  ok(mg && mg.yldPct != null, '洪城环境股息率分位已算 → ' + (mg && mg.yldPct));
  ok(mg && Array.isArray(mg.boll) && mg.boll.length >= 1, '洪城环境布林带已算（' + (mg && mg.boll ? mg.boll.length : 0) + ' 条）');

  // 空仓场景：带指标重算 rows，行对象应挂上 margin 与信号
  const d4 = new SQL.Database();
  d4.exec(SCHEMA);
  P._setDb(d4); P._seedInto(d4); P._readState();
  S.active = 'ALL';
  S.px = {};
  ['600461', '601000', '601298', '601033', '601077', '000651', '000001', '000598', '000429'].forEach(c => {
    const t = (sandbox.PANEL_CONFIG.targets || []).filter(x => x.code === c)[0];
    const mgc = P.marginOf(c);
    const px = (mgc && mgc.price) || (t && t.ref_px) || 10;
    S.px[c] = { price: px, prev: px, chg: 0, name: t ? t.name : c, at: Date.now() };
  });
  const r4 = P.rowsNow();
  const hc = r4.filter(r => r.code === '600461')[0];
  ok(hc && hc.margin, '行对象挂上了 margin 指标');
  ok(hc && typeof hc.marginBuy === 'boolean', '行对象有 marginBuy 信号 → ' + (hc && hc.marginBuy));
  ok(hc && hc.buyToTgtPct != null, '现价距目标买价已算 → ' + (hc && hc.buyToTgtPct));
  // 洪城环境现价 8.62 <= 目标买价 9.34 → 股息率达标，应判为可买
  ok(hc && hc.yldHit === true, '洪城环境现价低于目标买价 → 股息率达标可买');

  // buildPlan 应优先推荐 marginBuy 的标的
  const T4b = P.totals(r4);
  const plan4 = P.buildPlan(50000, r4, T4b);
  console.log('  带指标本金 50000 → 计划 ' + plan4.items.length + ' 项：' +
    plan4.items.map(x => x.r.name).join('、'));
  ok(plan4.items.length > 0, '带指标时仍能给出买入清单');
  ok(plan4.items.every(x => x.r.marginBuy), '推荐项均为 marginBuy 触发项');

  // 渲染不报错且表头 9 列
  P.render();
  ok(el('planBody').innerHTML.length > 0, '买入推荐表已渲染（新 9 列）');
